script:
// booking_ristourne — Global Ristourne Client Script (Sales Order)

const RISTOURNE_API    = "booking_ristourne.sales_order.get_available_for_sales_order";
const APPLIED_FIELD    = "discount_amount";                 // on applique ici
const TOGGLE_FIELD     = "custom_appliquer_ristourne";      // Check (Oui/Non)
const DISPONIBLE_FIELD = "custom_ristourne_disponible";     // HTML — note

// ---------- Utils ----------
function flt_(v) {
  if (frappe?.utils && typeof frappe.utils.flt === "function") return frappe.utils.flt(v || 0);
  const n = parseFloat(v); return Number.isFinite(n) ? n : 0;
}
function is_draft(frm) { return (frm.doc.docstatus || 0) === 0; }
function on_(frm){
  const v = frm.doc[TOGGLE_FIELD];
  return v === 1 || v === true || v === "Oui" || v === "Yes"; // tolérant
}
function can_compute(frm){ return !!(frm.doc.customer && frm.doc.transaction_date); }

// Ensure the HTML field actually renders the note
function set_note_html(frm, html){
  // Preferred: set df.options so it persists across rerenders
  try {
    frm.set_df_property(DISPONIBLE_FIELD, "options", html || "");
  } catch(e) {}
  // Fallback direct write if wrapper is available now
  const f = frm.get_field(DISPONIBLE_FIELD);
  if (f?.$wrapper) f.$wrapper.html(html || "");
  frm.refresh_field(DISPONIBLE_FIELD);
}

async function safe_call(opts){
  try { return await frappe.call(opts); }
  catch(e){ console.warn("Ristourne API error:", e); return { message: null }; }
}
async function fetch_availability(frm){
  const args = {
    customer: frm.doc.customer,
    transaction_date: frm.doc.transaction_date,
    grand_total: frm.doc.grand_total
  };
  const { message } = await safe_call({ method: RISTOURNE_API, args, freeze: false });
  return message || {};
}
async function set_apply_discount_on_grand_total(frm){
  if (!is_draft(frm)) return; // don't mutate submitted docs
  if (frm.doc.apply_discount_on !== "Grand Total") {
    await frm.set_value("apply_discount_on", "Grand Total");
  }
}
async function clear_discount(frm){
  if (!is_draft(frm)) return; // don't mutate submitted docs
  await set_apply_discount_on_grand_total(frm);
  if (flt_(frm.doc.discount_amount) !== 0) await frm.set_value("discount_amount", 0);
}

// ---------- Notifications ----------
function fmt_currency(frm, val){
  return frappe.format(val, {fieldtype:"Currency"}, {currency: frm.doc.currency});
}
function notify_applied(frm, amount){
  // Optional: avoid alerts on submitted docs
  if (!is_draft(frm)) return;
  frappe.show_alert({
    message: `✅ Ristourne appliquée : ${fmt_currency(frm, -Math.abs(amount))}`,
    indicator: "green"
  }, 5);
}
function notify_removed(){
  frappe.show_alert({
    message: "↩️ Ristourne retirée",
    indicator: "orange"
  }, 5);
}

// ---------- Core ----------
async function apply_or_clear_ristourne(frm, available_to_date, note_html, force_off=false){
  const available = flt_(available_to_date);
  const has = available > 0;

  // Show/hide the toggle & note field depending on eligibility
  frm.toggle_display(TOGGLE_FIELD, has);
  frm.toggle_display(DISPONIBLE_FIELD, has);
  set_note_html(frm, has ? (note_html || "") : "");

  // From here on, NEVER mutate fields if not draft
  if (!is_draft(frm)) {
    // read-only view on submitted/cancelled docs
    return;
  }

  // Track last state to emit alerts only when state truly changes
  const prev_on     = !!frappe.flags.__ristourne_on;
  const prev_amount = flt_(frappe.flags.__ristourne_amount);

  if (!has || force_off || !on_(frm)) {
    const was_applied = prev_on && prev_amount > 0 && flt_(frm.doc.discount_amount) > 0;
    await clear_discount(frm);

    // Notify only if something was applied before and now removed
    if (was_applied) notify_removed();

    frappe.flags.__ristourne_on = false;
    frappe.flags.__ristourne_amount = 0;
    return;
  }

  // note + forcer Grand Total
  await set_apply_discount_on_grand_total(frm);

  // appliquer plafonné par total (ou grand_total selon votre logique)
  const cap_base = flt_(frm.doc.total || 0); // peut être grand_total si souhaité
  const to_apply = Math.min(available, cap_base);

  const current = flt_(frm.doc.discount_amount);
  const changed = current !== to_apply;

  if (changed) {
    await frm.set_value(APPLIED_FIELD, to_apply);

    // Fire notifications:
    if (to_apply > 0) {
      // If previously off or different amount, tell user it’s applied/updated
      notify_applied(frm, to_apply);
    } else if (prev_on && prev_amount > 0) {
      // Edge-case: to_apply goes to 0 while toggle still ON
      notify_removed();
    }
  }

  // Update state flags
  frappe.flags.__ristourne_on = true;
  frappe.flags.__ristourne_amount = to_apply;
}

async function recompute_ristourne(frm, {force_off=false} = {}){
  if (!can_compute(frm)) {
    frm.toggle_display(TOGGLE_FIELD, false);
    frm.toggle_display(DISPONIBLE_FIELD, false);
    set_note_html(frm, "");
    if (is_draft(frm) && (on_(frm) || flt_(frm.doc.discount_amount) !== 0)) {
      await clear_discount(frm);
    }
    frappe.flags.__ristourne_on = false;
    frappe.flags.__ristourne_amount = 0;
    return;
  }

  if (frappe.flags.__ristourne_busy) return;
  try {
    frappe.flags.__ristourne_busy = true;
    const st = await fetch_availability(frm);
    const available = flt_(st?.available_to_date);
    const note_html = st?.note_html;
    await apply_or_clear_ristourne(frm, available, note_html, force_off);
  } finally {
    frappe.flags.__ristourne_busy = false;
  }
}

// Debounce pour éviter les recalculs multiples lors de l'édition d'items
const debounced_recompute = frappe?.utils?.debounce
  ? frappe.utils.debounce((frm) => recompute_ristourne(frm), 250)
  : (frm) => recompute_ristourne(frm);

// ---------- Form events ----------
frappe.ui.form.on("Sales Order", {
  onload:  async (frm) => { await recompute_ristourne(frm); },
  refresh: async (frm) => { await recompute_ristourne(frm); },

  // l'éligibilité change → forcer OFF et revalider
  customer:         async (frm) => { await recompute_ristourne(frm, { force_off: true }); },
  transaction_date: async (frm) => { await recompute_ristourne(frm, { force_off: true }); },

  // Recalcul si le total change (ERPNext met à jour grand_total après items/taxes)
  total:      async (frm) => { if (is_draft(frm) && on_(frm)) await recompute_ristourne(frm); },

  // Imposer Grand Total lorsque ON (draft only)
  apply_discount_on: async (frm) => {
    if (is_draft(frm) && on_(frm) && frm.doc.apply_discount_on !== "Grand Total") {
      await set_apply_discount_on_grand_total(frm);
    }
  },

  // Toggle
  [TOGGLE_FIELD]: async (frm) => {
    if (on_(frm)) await recompute_ristourne(frm);
    else          await recompute_ristourne(frm, { force_off: true });
  },

  // Safety: avant enregistrement, s'assurer que la ristourne est alignée (draft only)
  // before_save: async (frm) => {
  //   if (is_draft(frm) && on_(frm)) {
  //     await set_apply_discount_on_grand_total(frm);
  //     await recompute_ristourne(frm);
  //   }
  // },
});

// ---------- Item-level triggers (font évoluer le total) ----------
frappe.ui.form.on("Sales Order Item", {
  // tout ce qui peut impacter le total (draft only)
  item_code:          (frm) => is_draft(frm) && on_(frm) && debounced_recompute(frm),
  qty:                (frm) => is_draft(frm) && on_(frm) && debounced_recompute(frm),
  rate:               (frm) => is_draft(frm) && on_(frm) && debounced_recompute(frm),
  amount:             (frm) => is_draft(frm) && on_(frm) && debounced_recompute(frm),
  discount_percentage:(frm) => is_draft(frm) && on_(frm) && debounced_recompute(frm),
  discount_amount:    (frm) => is_draft(frm) && on_(frm) && debounced_recompute(frm),
  price_list_rate:    (frm) => is_draft(frm) && on_(frm) && debounced_recompute(frm),
  uom:                (frm) => is_draft(frm) && on_(frm) && debounced_recompute(frm),
  conversion_factor:  (frm) => is_draft(frm) && on_(frm) && debounced_recompute(frm),

  // quand la ligne se rend, certains champs recalculent → recheck soft (draft only)
  items_on_form_rendered: (frm) => is_draft(frm) && on_(frm) && debounced_recompute(frm),
});
